systemd-245.8-2.fc32.x86_64
polkit-0.116-7.fc32.x86_64

Fedora core 32 64 bit

```
systemd-run --scope -u isc_cache ccontrol start 201722B865D3
```
purpose not root user might able to start transient unit

```
cat /etc/polkit-1/rules.d/10-isc-cache.rules
polkit.addRule(function(action, subject) {
 if (action.id == "org.freedesktop.systemd1.manage-units" ) {
   polkit.log("action lookup unit=" + action.lookup("unit") );
   // !!! system-run  action.lookup("unit") undefined
   if ( action.lookup("unit") == "isc_cache.scope" && subject.isInGroup("cachemgr") ) {
     return polkit.Result.YES;
   }
  // ok systemctl start|stop isccache@<instance> for /etc/systemd/system/isccache@.service
  // purpose not root might start isc cache service if user memeber of cachemgr group
   if ( RegExp("isccache@[A-Za-z0-9_-]+.service").test(action.lookup("unit")) && subject.isInGroup("cachemgr") ) {
     return polkit.Result.YES;
   }

 }
});
```

